INSERT INTO `recipes` (`id`, `user_id`, `title`, `category`, `ingredients`, `description`, `steps`, `tags`, `likes_count`, `image_path`, `created_at`) VALUES
(1, 1, 'Classic Scrambled Eggs', 'Breakfast', '3 eggs\r\n2 tbsp milk\r\n1 tbsp butter\r\nSalt & pepper', 'A simple and soft scrambled egg dish perfect for a quick morning meal.', '1. Crack eggs into a bowl and whisk with milk.\r\n\r\n2. Melt butter in a pan over low heat.\r\n\r\n3. Pour egg mixture and gently stir until soft and fluffy.\r\n\r\n4. Season and serve warm.', 'eggs, quick, protein', 0, '/uploads/1763094151_Classic Scrambled Eggs.jpg', '2025-11-14 04:22:31'),
(2, 1, 'Chicken Fried Rice', 'Lunch', '1 cup cooked rice\r\n100g chicken breast (diced)\r\n1 egg\r\nMixed vegetables\r\nSoy sauce\r\nGarlic', 'A Malaysian-Chinese style fried rice with chicken, vegetables, and soy sauce.', '1. Stir-fry garlic and chicken until cooked.\r\n2. Add vegetables and stir for 1 minute.\r\n3. Add rice and soy sauce.\r\n4. Push rice aside, scramble egg, then mix everything.', 'Tags: one-pan', 0, '/uploads/1763094546_Chicken Fried Rice.jpg', '2025-11-14 04:29:06'),
(5, 1, 'Chicken Caesar Salad', 'Salad', 'Romaine lettuce\\r\\nGrilled chicken slices\\r\\nCroutons\\r\\nParmesan\\r\\nCaesar dressing', 'Crispy lettuce with grilled chicken, parmesan, and Caesar dressing.', '1. Chop lettuce and place in bowl.\\r\\n\\r\\n2. Add chicken, croutons, and cheese.\\r\\n\\r\\n3. Pour dressing and toss gently.', 'healthy, high-protein', 0, '/uploads/1763095182_Chicken Caesar Salad.jpg', '2025-11-14 04:39:42'),
(7, 2, 'Strawberry Smoothie', 'Beverage', '1 cup strawberries\r\n½ cup yogurt\r\nIce', 'A refreshing strawberry blend that takes under 2 minutes to make.', '1. Add strawberries and yogurt to blender.\r\n2. Add ice.\r\n3. Blend until smooth.', 'fruity, easy', 4, '/uploads/1763096017_Strawberry Smoothie.jpg', '2025-11-14 04:53:37'),
(9, 1, 'Mango Smoothie', 'Beverage', '1 ripe mango\r\n½ cup milk\r\nIce cubes\r\nHoney', 'A creamy, refreshing drink made with ripe mango and milk.', '1. Blend mango, milk, ice, and honey.\r\n\r\n2. Serve chilled.', 'drink, sweet', 1, '/uploads/1763097033_Mango Smoothie.jpg', '2025-11-14 05:10:33'),
(10, 2, 'Vanilla Ice Cream', 'Dessert', '2 cups heavy cream\r\n1 cup condensed milk\r\n1 tsp vanilla extract', 'A classic 3-ingredient vanilla ice cream made without complicated steps.', '1. Whip heavy cream until fluffy.\r\n\r\n2. Fold in condensed milk and vanilla.\r\n\r\n3. Freeze for 6 hours until firm.', 'sweet', 0, '/uploads/1763097253_Vanilla Ice Cream.jpg', '2025-11-14 05:14:13'),
(11, 3, 'Chocolate Ice Cream', 'Dessert', '2 cups heavy cream\r\n1 cup condensed milk\r\n2 tbsp cocoa powder', 'Smooth chocolate ice cream using cocoa powder and condensed milk.', '1. Whip cream until soft peaks form.\r\n\r\n2. Mix condensed milk with cocoa powder.\r\n\r\n3. Fold mixture into the cream.\r\n\r\n4. Freeze 6 hours.', 'sweet', 1, '/uploads/1763097523_Chocolate Ice Cream.jpg', '2025-11-14 05:18:43'),
(12, 3, 'Tomato Pasta', 'Pasta', '1 cup pasta (spaghetti or penne)\r\n1 cup tomato sauce\r\n2 cloves garlic (minced)\r\n1 tbsp olive oil\r\nSalt & pepper', 'A quick and simple pasta dish cooked in a light tomato sauce with garlic and herbs. Perfect for an easy lunch or dinner.', '1. Boil pasta until al dente and drain.\r\n\r\n2. Heat olive oil in a pan and sauté garlic.\r\n\r\n3. Add tomato sauce and simmer for 2 minutes.\r\n\r\n4. Add cooked pasta and mix well.\r\n\r\n5. Season with salt & pepper.\r\n\r\n6. Garnish with basil if available.', 'simple, healthy', 0, '/uploads/1763097847_Tomato Spaghetti.jpg', '2025-11-14 05:24:07'),
(13, 1, 'Strawberry Ice Cream', 'Dessert', '1 cup strawberries (blended)\\r\\n1 cup whipped cream\\r\\n½ cup condensed milk\\r\\n1 tsp lemon juice\\r\\n', 'A refreshing, fruity strawberry ice cream made with only 4 ingredients.', '1. Blend strawberries and lemon juice.\\r\\n2. Add condensed milk and mix.\\r\\n3. Fold in whipped cream.\\r\\n4. Freeze until solid.\\r\\n', 'fruity, sweet', 0, '/uploads/1763107717_Strawberry Ice Cream.jpg', '2025-11-14 08:08:37'),
(17, 1, 'Chocolate Drizzle Donuts With Rainbow Sprinkles', 'Dessert', 'For the Donut Dough:\r\n•	2 ½ cups all-purpose flour\r\n•	3 tbsp sugar\r\n•	2 ¼ tsp instant yeast\r\n•	½ tsp salt\r\n•	¾ cup warm milk\r\n•	2 tbsp melted butter\r\n•	1 large egg\r\n•	1 tsp vanilla extract\r\n•	Oil for frying\r\nFor the Chocolate Glaze:\r\n•	1 cup powdered sugar\r\n•	3 tbsp cocoa powder\r\n•	3–4 tbsp milk\r\n•	1 tsp vanilla extract\r\nFor the Vanilla Drizzle:\r\n•	½ cup powdered sugar\r\n•	1–2 tbsp milk\r\n•	½ tsp vanilla extract\r\nToppings:\r\n•	Rainbow sprinkles\r\n', 'Soft, fluffy fried donuts coated with rich chocolate glaze, drizzled with sweet vanilla icing, and topped with colorful rainbow sprinkles. Perfect for parties, snacks, or whenever you crave something sweet!', '1. In a large bowl, mix flour, sugar, yeast, and salt. Add warm milk, melted butter, egg, and vanilla. Mix until dough forms.\r\n2. Knead on a floured surface for about 5–7 minutes until smooth and elastic.\r\n3. Place dough in a greased bowl, cover, and let rise for 1 hour or until doubled in size.\r\n4. Roll dough to ½-inch thickness. Cut out donut shapes using a cutter or two round cups.\r\n5. Transfer cut donuts to a tray and let them rise for another 30 minutes.\r\n6. Heat oil to 180°C (350°F). Fry donuts until golden brown, about 1 minute per side. Place on paper towels to drain.\r\n7. Mix powdered sugar, cocoa, milk, and vanilla until smooth.\r\n8. Mix powdered sugar, milk, and vanilla until slightly thick but pourable.\r\n9. Dip each donut in chocolate glaze, drizzle with vanilla icing, and sprinkle generously with rainbow sprinkles.\r\n10. Let the glaze set for 10 minutes. Enjoy warm or room temperature!\r\n', 'sweet, donut, dessert, chocolate, kids-friendly, party snack', 0, '/uploads/1763519123_Donut.jpg', '2025-11-19 02:25:23');
